\begin{lemma}[Normal-kernel wrapping incidence]\label{lem:wrapping}
Let the canonical resolved system carry the annular-tower typing of Definition~\ref{def:canonical-resolved-system}.  If \(N\ne\{1\}\), then
\begin{equation}\label{eq:wrapping-in-limit-set}
\zeta_-,\zeta_+\in\Lambda(N).
\end{equation}
\end{lemma}

\begin{proposition}[Base-change propagation through exact equalizers]\label{prop:base-change}
Let
\[
X\xrightarrow{\ i\ }Z\xleftarrow{\ f\ }Y
\]
be continuous maps, and suppose
\[
i=e\circ q,\qquad X\xrightarrow{\ q\ }P\xrightarrow{\ e\ }Z,
\]
where \(q\) is a covering and \(e\) is an embedding.  Form
\[
E=X\times_ZY,\qquad R=P\times_ZY,
\]
and define
\begin{equation}\label{eq:base-change-maps}
q'\colon E\to R,\quad q'(x,y)=(q(x),y);
\qquad
e'\colon R\to Y,\quad e'(p,y)=y;
\qquad
i'\colon E\to Y,\quad i'(x,y)=y.
\end{equation}
Then:
\begin{enumerate}
\item \(q'\) is the pullback covering of \(q\) (along the projection \(R\to P\)); in particular the square
\[
\begin{array}{ccc}
E&\xrightarrow{\ q'\ }&R\\[2pt]
\big\downarrow&&\big\downarrow\\[2pt]
X&\xrightarrow{\ q\ }&P
\end{array}
\]
(vertical maps the first-coordinate projections) is cartesian;
\item \(e'\) is a topological embedding;
\item \(i'=e'\circ q'\);
\item \(i'\) and \(q'\) have the same kernel pair; and
\item for every \((p,y)\in R\),
\begin{equation}\label{eq:fiber-bijection}
(q')^{-1}(p,y)=\{(x,y):q(x)=p\}\cong q^{-1}(p).
\end{equation}
\end{enumerate}
Hence infinite collision fibers remain infinite under the full base-change equalizer.
\end{proposition}

theorems.proof_latex:
\begin{proof}
Apply Proposition~\ref{prop:base-change} with \(X=Y=\mathbf U^{r+1}\), \(Z=\mathbf U^{r}\), \(i=i_r\), \(f=f_r\), \(q=q_r\), \(e=e_r\); then \(E=\mathbf U^{r+2}\), \(R=P_{r+1}\), and the displayed maps are exactly \eqref{eq:base-change-maps}.  Conclusions (1)--(5) of the proposition give the asserted covering, embedding, factorization, kernel-pair, and fiber statements at stage \(r+1\).  Iterating from a stage at which the factorization holds propagates it, together with the cardinality of every fiber, to all subsequent stages.
\end{proof}

